# SPDX-License-Identifier: MIT
# Independent /proc/PID/limits reader for prlimit fixtures (takeover root).
# Applies prlimit.c's documented formats to the kernel's view of the limits
# and compares the candidate's captured output; it never runs the candidate.
import json, sys

NAMES = {'Max cpu time': 'CPU', 'Max file size': 'FSIZE', 'Max data size': 'DATA', 'Max stack size': 'STACK',
         'Max core file size': 'CORE', 'Max resident set': 'RSS', 'Max processes': 'NPROC',
         'Max open files': 'NOFILE', 'Max locked memory': 'MEMLOCK', 'Max address space': 'AS',
         'Max file locks': 'LOCKS', 'Max pending signals': 'SIGPENDING', 'Max msgqueue size': 'MSGQUEUE',
         'Max nice priority': 'NICE', 'Max realtime priority': 'RTPRIO', 'Max realtime timeout': 'RTTIME'}


def limits(pid):
    rows = {}
    with open('/proc/%s/limits' % pid) as handle:
        for line in handle.read().splitlines()[1:]:
            rows[NAMES[line[:26].strip()]] = (line[26:47].strip(), line[47:68].strip())
    return dict(sorted(rows.items()))


def obj(pid, name, value):
    return '{"pid":%s,"resource":"%s","soft":"%s","hard":"%s"}' % (pid, name, value[0], value[1])


def main():
    cmd, pid, a = sys.argv[1], sys.argv[2], sys.argv[3:]
    lim = limits(pid)
    got = open(a[-1]).read()
    if cmd == 'text':
        want = ''.join('%s %s %s\n' % (n, s, h) for n, (s, h) in lim.items())
    elif cmd == 'raw':
        want = ''.join('%s\t%s\t%s\n' % (n, s, h) for n, (s, h) in lim.items())
    elif cmd == 'json':
        want = '{"pid":%s,"limits":[%s]}\n' % (pid, ','.join(obj(pid, n, v) for n, v in lim.items()))
        try:
            parsed = json.loads(got)
            valid = parsed['pid'] == int(pid) and [d['resource'] for d in parsed['limits']] == list(lim)
        except (ValueError, KeyError, TypeError):
            valid = False
        print('json parses=%s' % ('yes' if valid else 'no'), end=' ')
    elif cmd == 'one':
        want = obj(pid, a[0], lim[a[0]]) + '\n'
        cmd = 'json-%s soft=%s hard=%s' % (a[0], lim[a[0]][0], lim[a[0]][1])
    print('%s rows=%d %s' % (cmd, len(lim), 'match' if got == want else 'differ'))


main()
